from decimal import Decimal
from ledgerly.adjustments import goodwill_credit
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(total="2000.00", status="issued"):
    return Invoice("inv_1","cus_1",lines=[LineItem("x",1,Decimal(total))],status=status)

# at threshold, no approval
print(goodwill_credit(inv(), Decimal("1000.00"), "ok"))
# above threshold, no approval
try:
    goodwill_credit(inv(), Decimal("1000.01"), "x")
except BillingError as e:
    print("raised", e.code)
# above threshold with approval
print(goodwill_credit(inv(), Decimal("1000.01"), "x", approved_by="mgr"))
# non-positive
try:
    goodwill_credit(inv(), Decimal("0"), "x")
except BillingError as e:
    print("raised", e.code)
# exceeds total
try:
    goodwill_credit(inv("10.00"), Decimal("20.00"), "x")
except BillingError as e:
    print("raised", e.code)
# not issued
try:
    goodwill_credit(inv(status="draft"), Decimal("1.00"), "x")
except BillingError as e:
    print("raised", e.code)
EOF"}

